<template>
  <div>
    <el-row :gutter="20" style="margin-bottom: 20px;">
      <el-col :span="12">
        <el-input v-model="searchQuery" placeholder="搜索用户名/姓名" @keyup.enter="handleSearch" />
      </el-col>
      <el-col :span="12" style="text-align: right;">
        <el-button type="primary" @click="handleAdd">新增用户</el-button>
      </el-col>
    </el-row>

    <el-table :data="userList" v-loading="loading" border>
      <el-table-column prop="id" label="ID" width="80" />
      <el-table-column prop="username" label="用户名" />
      <el-table-column prop="realName" label="姓名" />
      <el-table-column prop="role" label="角色" :formatter="roleFormatter" />
      <el-table-column prop="email" label="邮箱" />
      <el-table-column prop="phone" label="电话" />
      <el-table-column label="操作" width="200">
        <template #default="scope">
          <el-button size="mini" @click="handleEdit(scope.row)">编辑</el-button>
          <el-button size="mini" type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
        </template>
      </el-table-column>
    </el-table>

    <el-pagination
      @size-change="handleSizeChange"
      @current-change="handleCurrentChange"
      :current-page="page"
      :page-sizes="[10, 20, 50]"
      :page-size="pageSize"
      layout="total, sizes, prev, pager, next, jumper"
      :total="total"
      style="margin-top: 20px;"
    />

    <!-- 新增/编辑对话框 -->
    <!-- eslint-disable-next-line vue/no-deprecated-v-bind-sync -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="500px">
      <el-form :model="form" :rules="formRules" ref="form" label-width="80px">
        <el-form-item label="用户名" prop="username">
          <el-input v-model="form.username" :disabled="!!editId" />
        </el-form-item>
        <el-form-item label="密码" prop="password" v-if="!editId">
          <el-input v-model="form.password" type="password" />
        </el-form-item>
        <el-form-item label="姓名" prop="realName">
          <el-input v-model="form.realName" />
        </el-form-item>
        <el-form-item label="角色" prop="role">
          <el-select v-model="form.role" placeholder="请选择">
            <el-option label="管理员" value="admin" />
            <el-option label="普通用户" value="user" />
          </el-select>
        </el-form-item>
        <el-form-item label="邮箱" prop="email">
          <el-input v-model="form.email" />
        </el-form-item>
        <el-form-item label="电话" prop="phone">
          <el-input v-model="form.phone" />
        </el-form-item>
      </el-form>
      <template #footer>
        <span>
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="saveUser">保存</el-button>
        </span>
      </template>
    </el-dialog>
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

export default {
  name: 'UserManagement',
  data() {
    return {
      searchQuery: '',
      page: 1,
      pageSize: 10,
      dialogVisible: false,
      editId: null,
      form: {
        username: '',
        password: '',
        realName: '',
        role: 'user',
        email: '',
        phone: ''
      },
      formRules: {
        username: [{ required: true, message: '请输入用户名', trigger: 'blur' }],
        password: [{ required: true, message: '请输入密码', trigger: 'blur' }],
        realName: [{ required: true, message: '请输入姓名', trigger: 'blur' }],
        role: [{ required: true, message: '请选择角色', trigger: 'change' }]
      }
    }
  },
  computed: {
    ...mapState('user', ['list', 'total', 'loading']), // 假设在 store/modules/user.js 中定义了
    userList() {
      return this.list
    },
    dialogTitle() {
      return this.editId ? '编辑用户' : '新增用户'
    }
  },
  created() {
    this.fetchData()
  },
  methods: {
    ...mapActions('user', ['fetchUsers', 'addUser', 'updateUser', 'deleteUser']),
    fetchData() {
      const params = {
        page: this.page,
        pageSize: this.pageSize,
        keyword: this.searchQuery
      }
      this.fetchUsers(params)
    },
    handleSearch() {
      this.page = 1
      this.fetchData()
    },
    handleSizeChange(val) {
      this.pageSize = val
      this.page = 1
      this.fetchData()
    },
    handleCurrentChange(val) {
      this.page = val
      this.fetchData()
    },
    handleAdd() {
      this.editId = null
      this.form = { username: '', password: '', realName: '', role: 'user', email: '', phone: '' }
      this.dialogVisible = true
    },
    handleEdit(row) {
      this.editId = row.id
      this.form = { ...row }
      delete this.form.password // 编辑时不显示密码
      this.dialogVisible = true
    },
    async handleDelete(id) {
      await this.$confirm('确认删除该用户吗？', '提示', { type: 'warning' })
      await this.deleteUser(id)
      this.$message.success('删除成功')
    },
    saveUser() {
      this.$refs.form.validate(async valid => {
        if (valid) {
          if (this.editId) {
            await this.updateUser({ id: this.editId, data: this.form })
          } else {
            await this.addUser(this.form)
          }
          this.$message.success('保存成功')
          this.dialogVisible = false
          this.fetchData()
        }
      })
    },
    roleFormatter(row) {
      const map = { admin: '管理员', user: '普通用户' }
      return map[row.role] || row.role
    }
  }
}
</script>